// A bead race powered by conservation of energy, not by a decorative speed tween.
import {cycloid,bezierTrack,descentTrack,pointAtTime,clamp} from './gallery-models.js';
import {exhibit,background,path,dot,button,field,bind} from './gallery-kit.js';
export function fastestSlide(root,opts){
  const {t}=opts;const end=[4,2],cy=cycloid(end);let handles=[[.9,2.6],[2.8,2.9]],tracks=[],time=0,playing=false,drag=null,dirty=true,selected=0,visible=[true,true,true];
  const o=exhibit(root,opts,t('Dessine une descente avec les deux poignées. Sur la figure, [ et ] choisissent une poignée et les flèches la déplacent. Avant la course, prédis la gagnante. Coche les pistes à comparer. Les billes partent ensemble, sans vitesse initiale, et glissent sans frottement.','Shape a descent with the two handles. On the canvas, [ and ] select a handle and arrow keys move it. Predict the winner before racing. Check the tracks to compare. The beads start together, from rest, and slide without friction.'),button('bs-race',t('Lancer la course','Race the beads'),true)+field('bs-time',t('Temps de la course (s)','Race time (s)'),0,2,.005,0)+`<fieldset class="exhibit-choices"><legend>${t('Afficher les pistes','Show tracks')}</legend>${[t('Ta courbe','Your curve'),t('Droite','Straight line'),t('Cycloïde','Cycloid')].map((name,i)=>`<label class="act-check"><input type="checkbox" id="bs-show-${i}" checked>${name}</label>`).join('')}</fieldset>`,
    `<p>${t('La droite est la plus courte. Une pente initiale plus raide permet pourtant de prendre de la vitesse plus tôt. La cycloïde minimise le temps dans ce modèle idéal, sous gravité uniforme.','The straight line is shortest. A steeper initial descent can nevertheless gain speed earlier. The cycloid minimises travel time in this ideal model under uniform gravity.')}</p><p>v² = 2gy, g = 9.81 m/s². ${t('La hauteur y est mesurée vers le bas depuis le départ. Les temps de ta courbe sont calculés sur 240 segments, exactement sur chaque segment. Le temps de la cycloïde affiché est analytique.','Depth y is measured downwards from the start. Your curve is timed on 240 segments, exactly on each segment. The displayed cycloid time is analytical.')}</p><p><a href="https://mathshistory.st-andrews.ac.uk/HistTopics/Brachistochrone/" target="_blank" rel="noopener noreferrer">${t('Le problème de la brachistochrone','The brachistochrone problem')}</a></p>`);
  const g=o.g,X=p=>[65+p[0]*125,55+p[1]*94],inv=p=>[(p[0]-65)/125,(p[1]-55)/94],fmt=x=>Number.isFinite(x)?x.toFixed(3):'∞';
  const labels=[t('Ta courbe','Your curve'),t('Droite','Straight line'),t('Cycloïde','Cycloid')];
  function rebuild(){tracks=[descentTrack(bezierTrack(handles,end)),descentTrack([[0,0],end]),descentTrack(cy.points)];tracks[2].total=cy.time;tracks[2].times=tracks[2].points.map((_,i)=>cy.time*i/(tracks[2].points.length-1));root.querySelector('#bs-time').max=Math.max(...tracks.map(x=>x.total),1).toFixed(3);dirty=false;}
  function changed(){playing=false;time=0;dirty=true;o.redraw();}
  visible.forEach((_,i)=>o.on(root.querySelector(`#bs-show-${i}`),'change',e=>{visible[i]=e.target.checked;playing=false;root.querySelector('#bs-race').disabled=!visible.some(Boolean);o.redraw();}));
  bind(root,'bs-time',v=>{time=v;playing=false;o.redraw();},v=>v.toFixed(3));
  o.on(root.querySelector('#bs-race'),'click',()=>{if(dirty)rebuild();time=0;playing=!opts.reduced();if(opts.reduced())time=Math.max(0,...tracks.filter((_,i)=>visible[i]).map(x=>x.total));o.redraw();});
  o.on(o.cv,'pointerdown',e=>{const p=o.point(e);drag=visible[0]?handles.findIndex(h=>Math.hypot(X(h)[0]-p[0],X(h)[1]-p[1])<26):-1;if(drag<0){drag=null;return;}selected=drag;o.cv.setPointerCapture?.(e.pointerId);changed();});
  o.on(o.cv,'pointermove',e=>{if(drag===null)return;const p=inv(o.point(e));handles[drag]=[clamp(p[0],drag===0?.03:handles[0][0]+.05,drag===0?handles[1][0]-.05:3.97),clamp(p[1],.05,3.6)];dirty=true;o.redraw();});
  o.on(o.cv,'pointerup',()=>drag=null);o.cancelDrag=()=>drag=null;
  o.on(o.cv,'keydown',e=>{if(e.shiftKey)return;if(e.key==='['||e.key===']'){selected=1-selected;return;}const d={ArrowLeft:[-.04,0],ArrowRight:[.04,0],ArrowUp:[0,-.04],ArrowDown:[0,.04]}[e.key];if(d){e.preventDefault();handles[selected]=[clamp(handles[selected][0]+d[0],selected===0?.03:handles[0][0]+.05,selected===0?handles[1][0]-.05:3.97),clamp(handles[selected][1]+d[1],.05,3.6)];changed();}});
  let frame=0;
  o.animate(dt=>{if(dirty)rebuild();if(playing){time+=dt;const finish=Math.max(0,...tracks.filter((_,i)=>visible[i]).map(x=>x.total));if(time>=finish){time=finish;playing=false;}}const C=background(o),colors=[C.accent,C.obj2,C.pos];
    g.font='14px system-ui';g.textAlign='left';g.fillStyle=C.muted;g.fillText(t('Départ : y = 0','Start: y = 0'),55,30);g.fillText(t('1 m vers le bas','1 m down'),65,430);
    for(let y=0;y<=3;y++)path(g,[X([0,y]),X([4,y])],{stroke:C.line,width:.6});
    tracks.forEach((tr,i)=>{if(!visible[i])return;path(g,tr.points.map(X),{stroke:colors[i],width:3});const tau=Math.min(time,tr.total),theta=tau/Math.sqrt(cy.a/9.81),pos=i===2?[cy.a*(theta-Math.sin(theta)),cy.a*(1-Math.cos(theta))]:pointAtTime(tr,tau);dot(g,X(pos),colors[i],8);g.fillStyle=colors[i];g.fillText(`${labels[i]}: ${fmt(tr.total)} s`,325,345+i*26);});
    if(visible[0]){path(g,[[0,0],handles[0]].map(X),{stroke:C.muted,width:1});path(g,[handles[1],end].map(X),{stroke:C.muted,width:1});handles.forEach((p,i)=>dot(g,X(p),i===selected?C.ink:C.accent,8,`P${i+1}`));}dot(g,X([0,0]),C.ink,5,'A');dot(g,X(end),C.ink,5,'B');
    root.querySelector('#bs-time').value=time;root.querySelector('#bs-time-out').textContent=time.toFixed(3);
    if(++frame%12===0||!dt)o.read(`${t('Temps','Time')}: ${fmt(time)} s · ${labels[0]} ${fmt(tracks[0].total)} s · ${labels[1]} ${fmt(tracks[1].total)} s · ${labels[2]} ${fmt(cy.time)} s. ${t('Ta courbe et la droite : durées numériques.','Your curve and straight line: numerical timings.')}`);
  });return o.stop;
}
